# --- резервы ------------------------------------------------------------

def reserve(
    self,
    order_id: str,
    lines: Iterable[tuple[str, str, int] | ReservationLine],
    ttl: timedelta | None = None,
) -> Reservation:
    """Резервирует товар под заказ сразу по всем строкам или не резервирует ничего."""
    _validate_code(order_id, "order_id")
    if ttl is None:
        ttl = DEFAULT_RESERVATION_TTL
    _validate_ttl(ttl)
    normalized = tuple(_normalize_line(line) for line in lines)
    if not normalized:
        raise ValidationError("reservation must contain at least one line")
    for line in normalized:
        self._check_position(line.warehouse, line.sku)
        _validate_qty(line.qty)
    now = self._clock.now()
    existing = self._store.get_reservation(order_id)
    if existing is not None and effective_status(existing, now) in (
        ReservationStatus.ACTIVE,
        ReservationStatus.CONFIRMED,
    ):
        raise DuplicateReservationError(order_id)
    requested: dict[tuple[str, str], int] = {}
    for line in normalized:
        key = (line.warehouse, line.sku)
        requested[key] = requested.get(key, 0) + line.qty
    for (warehouse, sku), qty in requested.items():
        available = self._available(warehouse, sku, now)
        if qty > available:
            raise InsufficientStockError(warehouse, sku, qty, available)
    record = ReservationRecord(order_id, normalized, now, now + ttl)
    self._store.put_reservation(record)
    expires = format_timestamp(record.expires_at)
    for line in normalized:
        self._log.append(
            now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku, qty=line.qty,
            expires=expires,
        )
    logger.info("reserved order %s (%d lines)", order_id, len(normalized))
    return snapshot(record, now)

def confirm(self, order_id: str) -> Reservation:
    """Превращает активный резерв в отгрузку."""
    now = self._clock.now()
    record = self._find_active(order_id, now)
    needed: dict[tuple[str, str], int] = {}
    for line in record.lines:
        key = (line.warehouse, line.sku)
        needed[key] = needed.get(key, 0) + line.qty
    for (warehouse, sku), qty in needed.items():
        physical = self._store.get_qty(warehouse, sku)
        if qty > physical:
            raise InsufficientStockError(warehouse, sku, qty, physical)
    for line in record.lines:
        self._write_issue(line.warehouse, line.sku, line.qty, order_id)
    record.status = ReservationStatus.CONFIRMED
    self._log.append(now, "RESERVE_CONFIRM", order=order_id)
    logger.info("confirmed order %s", order_id)
    return snapshot(record, now)

def cancel(self, order_id: str) -> Reservation:
    """Освобождает активный резерв; для отменённого и истёкшего — без изменений."""
    now = self._clock.now()
    record = self._find_reservation(order_id)
    status = effective_status(record, now)
    if status is ReservationStatus.CONFIRMED:
        raise ReservationStateError(order_id)
    if status is ReservationStatus.ACTIVE:
        record.status = ReservationStatus.CANCELLED
        self._log.append(now, "RESERVE_CANCEL", order=order_id)
        logger.info("cancelled order %s", order_id)
    return snapshot(record, now)

def extend(self, order_id: str, ttl: timedelta) -> Reservation:
    """Продлевает активный резерв до ``now + ttl``; срок не сокращается."""
    _validate_ttl(ttl)
    now = self._clock.now()
    record = self._find_active(order_id, now)
    new_expires = now + ttl
    if new_expires > record.expires_at:
        record.expires_at = new_expires
        self._log.append(
            now, "RESERVE_EXTEND", order=order_id, expires=format_timestamp(new_expires)
        )
        logger.info("extended order %s", order_id)
    return snapshot(record, now)

